// Bom: EntityGraph carrega items em 1 JOIN
@EntityGraph(attributePaths = {"items"})
List<Order> findAllByUserId(UUID userId);

// Ou JOIN FETCH pontual em consulta específica
@Query("select o from Order o join fetch o.items where o.user.id = :uid")
List<Order> findWithItems(UUID uid);

public record OrderSummary(UUID id, String status, BigDecimal total) {}

@Query("""
    select new com.ffv.OrderSummary(o.id, o.status, sum(i.price * i.qty))
    from Order o join o.items i
    where o.user.id = :uid
    group by o.id, o.status
""")
List<OrderSummary> summariesByUser(UUID uid);
